import AsyncStorage from '@react-native-async-storage/async-storage';
import { supabase } from '../../shared/lib/supabase';
import { AsyncLock } from '../../shared/lib/async-lock';
import { golfService } from './golf.service';
import { SYNC_STATUS } from './golf.constants';
import type { ClubCourseInfo, ClubInfo, ClubSummary, GolfRound } from './golf.types';
import { logger } from '../../shared/utils/logger';

const BASE_STORAGE_KEY = '@golf_rounds_data';
const PENDING_SYNC_KEY = '@pending_sync_ids';
const storageLock = new AsyncLock();
const syncLocks = new Map<string, AsyncLock>();

/** Supabase DB Row Types for Internal Mapping */
interface DbHoleDistance {
    tee_color: string;
    distance_meter: number;
}

interface DbHole {
    id: string;
    course_id: string;
    hole_number: number;
    par: number;
    handicap_idx?: number;
    hole_distances: DbHoleDistance[];
}

interface DbCourse {
    id: string;
    club_id: string;
    name: string;
    hole_count: number;
    golf_holes: DbHole[];
}

interface DbClub {
    id: string;
    name: string;
    golf_courses: {
        id: string;
        name: string;
        hole_count: number;
    }[];
}

let storageKeyPromise: Promise<string | null> | null = null;

function getStorageKey(): Promise<string | null> {
    if (storageKeyPromise) return storageKeyPromise;

    storageKeyPromise = supabase.auth.getSession().then(({ data: { session } }) => {
        if (!session?.user?.id) {
            return null;
        }
        return `${BASE_STORAGE_KEY}_${session.user.id}`;
    });

    return storageKeyPromise;
}

supabase.auth.onAuthStateChange(() => {
    storageKeyPromise = null;
});

export const roundRepository = {
    async getAllRounds(): Promise<GolfRound[]> {
        return storageLock.run(async () => {
            try {
                const key = await getStorageKey();
                if (!key) return [];
                const jsonValue = await AsyncStorage.getItem(key);
                const localRounds: GolfRound[] = jsonValue != null ? JSON.parse(jsonValue) : [];
                return localRounds;
            } catch (e) {
                console.error('Failed to fetch rounds from local storage', e);
                return [];
            }
        });
    },

    async pullRoundsFromSupabase(sessionOverride?: import('@supabase/supabase-js').Session | null): Promise<{ success: boolean; count: number; error?: unknown }> {
        return storageLock.run(async () => {
            try {
                const session = sessionOverride ?? (await supabase.auth.getSession()).data.session;
                if (!session) return { success: false, count: 0 };

                const { data: roundsData, error: roundsError } = await supabase
                    .from('rounds')
                    .select('*')
                    .eq('user_id', session.user.id)
                    .order('date', { ascending: false });

                if (roundsError) throw roundsError;
                if (!roundsData || roundsData.length === 0) return { success: true, count: 0 };

                const roundIds = roundsData.map(r => r.id);
                const { data: holesData, error: holesError } = await supabase
                    .from('holes')
                    .select('*')
                    .in('round_id', roundIds);

                if (holesError) throw holesError;

                const remoteRounds: GolfRound[] = roundsData.map(r => ({
                    id: r.id,
                    date: r.date,
                    courseName: r.course_name,
                    courseType: r.course_type,
                    teeColor: r.tee_color,
                    outCourseId: r.out_course_id,
                    inCourseId: r.in_course_id,
                    memo: r.memo || '',
                    updatedAt: r.updated_at ? new Date(r.updated_at).getTime() : Date.now(),
                    holes: (holesData || [])
                        .filter(h => h.round_id === r.id)
                        .map(h => ({
                            holeNo: h.hole_no,
                            par: h.par,
                            stroke: h.stroke,
                            putt: h.putt,
                            isFairway: h.is_fairway,
                            isGIR: h.is_gir,
                            ob: h.ob,
                            penalty: h.penalty,
                            missShot: h.miss_shot
                        }))
                        .sort((a, b) => a.holeNo - b.holeNo)
                }));

                const key = await getStorageKey();
                if (!key) return { success: false, count: 0 };
                const localJson = await AsyncStorage.getItem(key);
                const localRounds: GolfRound[] = localJson ? JSON.parse(localJson) : [];

                const mergedRounds = golfService.resolveMergedRounds(localRounds, remoteRounds);
                await AsyncStorage.setItem(key, JSON.stringify(mergedRounds));
                return { success: true, count: remoteRounds.length };
            } catch (e) {
                console.error('[roundRepository] pullRoundsFromSupabase failed:', e);
                return { success: false, count: 0, error: e };
            }
        });
    },

    async saveRound(newRound: GolfRound): Promise<void> {
        return storageLock.run(async () => {
            try {
                const roundToSave = { ...newRound, updatedAt: Date.now() };
                const key = await getStorageKey();
                if (!key) throw new Error('Authentication required');
                const jsonValue = await AsyncStorage.getItem(key);
                const existingRounds: GolfRound[] = jsonValue != null ? JSON.parse(jsonValue) : [];
                const updatedRounds = [roundToSave, ...existingRounds.filter(r => r.id !== newRound.id)];
                await AsyncStorage.setItem(key, JSON.stringify(updatedRounds));
            } catch (e) {
                console.error('Failed to save round', e);
            }
        });
    },

    async syncRoundToSupabase(round: GolfRound, retries = 2): Promise<{ success: boolean; error?: unknown }> {
        // Round ID별 비동기 Lock 확보 (Race Condition 방지)
        if (!syncLocks.has(round.id)) {
            syncLocks.set(round.id, new AsyncLock());
        }
        const lock = syncLocks.get(round.id)!;

        return lock.run(async () => {
            const performSync = async (): Promise<void> => {
                const { data: { session } } = await supabase.auth.getSession();
                if (!session) throw new Error('Not authenticated');

                const { error: roundError } = await supabase
                    .from('rounds')
                    .upsert({
                        id: round.id,
                        user_id: session.user.id,
                        date: round.date,
                        course_name: round.courseName,
                        course_type: round.courseType,
                        tee_color: round.teeColor,
                        out_course_id: round.outCourseId,
                        in_course_id: round.inCourseId,
                        memo: round.memo,
                        updated_at: new Date(round.updatedAt || Date.now()).toISOString()
                    });

                if (roundError) throw roundError;

                if (round.holes.length > 0) {
                    const holesToSync = round.holes.map(h => ({
                        round_id: round.id,
                        hole_no: h.holeNo,
                        par: h.par,
                        stroke: h.stroke,
                        putt: h.putt,
                        is_fairway: h.isFairway,
                        is_gir: h.isGIR,
                        ob: h.ob,
                        penalty: h.penalty,
                        miss_shot: h.missShot
                    }));

                    const { error: holeError } = await supabase
                        .from('holes')
                        .upsert(holesToSync, { onConflict: 'round_id,hole_no' });

                    if (holeError) throw holeError;
                }
            };

            let currentAttempt = 0;
            const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

            while (currentAttempt <= retries) {
                try {
                    await performSync();
                    logger.sync(`Successfully synced round ${round.id} (Attempt ${currentAttempt + 1})`);
                    await this._removeFromSyncQueue(round.id);
                    return { success: true };
                } catch (e: unknown) {
                    currentAttempt++;
                    const message = e instanceof Error ? e.message : String(e);
                    // Use type guard for status check
                    const errStatus = (e && typeof e === 'object' && 'status' in e) ? (e as {status: number}).status : undefined;
                    const isNetworkError = message.includes('Network') || errStatus === 0 || !errStatus;

                    if (currentAttempt <= retries && isNetworkError) {
                        const backoff = Math.pow(2, currentAttempt) * 1000;
                        logger.warn(`Sync failed for ${round.id}, retrying in ${backoff}ms...`, message);
                        await delay(backoff);
                        continue;
                    }

                    logger.error(`[roundRepository] syncRoundToSupabase final failure for ${round.id}:`, e);
                    await this._addToSyncQueue(round.id);
                    return { success: false, error: e };
                }
            }
            return { success: false, error: 'Max retries reached' };
        });
    },

    async _addToSyncQueue(roundId: string) {
        try {
            const queueStr = await AsyncStorage.getItem(PENDING_SYNC_KEY);
            const queue: string[] = queueStr ? JSON.parse(queueStr) : [];
            if (!queue.includes(roundId)) {
                queue.push(roundId);
                await AsyncStorage.setItem(PENDING_SYNC_KEY, JSON.stringify(queue));
            }
        } catch (e) {
            console.error('Failed to add to sync queue', e);
        }
    },

    async _removeFromSyncQueue(roundId: string) {
        try {
            const queueStr = await AsyncStorage.getItem(PENDING_SYNC_KEY);
            if (!queueStr) return;
            const queue: string[] = JSON.parse(queueStr);
            const filtered = queue.filter(id => id !== roundId);
            await AsyncStorage.setItem(PENDING_SYNC_KEY, JSON.stringify(filtered));
        } catch (e) {
            console.error('Failed to remove from sync queue', e);
        }
    },

    async retryPendingSyncs(): Promise<{ attempted: number; success: number }> {
        try {
            const queueStr = await AsyncStorage.getItem(PENDING_SYNC_KEY);
            if (!queueStr) return { attempted: 0, success: 0 };

            const queue: string[] = JSON.parse(queueStr);
            if (queue.length === 0) return { attempted: 0, success: 0 };

            const rounds = await this.getAllRounds();
            let successCount = 0;

            for (const roundId of queue) {
                const round = rounds.find(r => r.id === roundId);
                if (round) {
                    const result = await this.syncRoundToSupabase(round);
                    if (result.success) successCount++;
                } else {
                    // Round no longer exists locally, remove from queue
                    await this._removeFromSyncQueue(roundId);
                }
            }
            return { attempted: queue.length, success: successCount };
        } catch (e: unknown) {
            console.error('Retry pending syncs failed', e);
            return { attempted: 0, success: 0 };
        }
    },

    async getSyncQueueCount(): Promise<number> {
        try {
            const queueStr = await AsyncStorage.getItem(PENDING_SYNC_KEY);
            if (!queueStr) return 0;
            const queue: string[] = JSON.parse(queueStr);
            return queue.length;
        } catch (e) {
            return 0;
        }
    },

    async getCurrentRoundId(): Promise<string | null> {
        try {
            const userIdKey = await getStorageKey();
            if (!userIdKey) return null;
            const currentRoundKey = `${userIdKey}_current_id`;
            return await AsyncStorage.getItem(currentRoundKey);
        } catch (e) {
            return null;
        }
    },

    async setCurrentRoundId(roundId: string | null): Promise<void> {
        try {
            const userIdKey = await getStorageKey();
            if (!userIdKey) return;
            const currentRoundKey = `${userIdKey}_current_id`;
            if (roundId === null) {
                await AsyncStorage.removeItem(currentRoundKey);
            } else {
                await AsyncStorage.setItem(currentRoundKey, roundId);
            }
        } catch (e) {
            console.error('Failed to set current round ID', e);
        }
    },

    async syncAllLocalRounds(): Promise<{ total: number; success: number; errors: unknown[] }> {
        const rounds = await this.getAllRounds();
        const results = await Promise.all(rounds.map(round => this.syncRoundToSupabase(round)));

        const errors: unknown[] = results
            .filter(r => !r.success)
            .map((r, i) => ({ id: rounds[i].id, error: r.error }));

        return { total: rounds.length, success: rounds.length - errors.length, errors };
    },

    async deleteRound(roundId: string): Promise<void> {
        return storageLock.run(async () => {
            try {
                const key = await getStorageKey();
                if (!key) throw new Error('Authentication required');
                const jsonValue = await AsyncStorage.getItem(key);
                const existingRounds: GolfRound[] = jsonValue != null ? JSON.parse(jsonValue) : [];
                const updatedRounds = existingRounds.filter(r => r.id !== roundId);
                await AsyncStorage.setItem(key, JSON.stringify(updatedRounds));

                const currentId = await this.getCurrentRoundId();
                if (currentId === roundId) {
                    await this.setCurrentRoundId(null);
                }

                await this._removeFromSyncQueue(roundId);

                // Cleanup sync lock for the deleted round
                syncLocks.delete(roundId);

                const { error } = await supabase.from('rounds').delete().eq('id', roundId);
                if (error) throw error;

            } catch (e) {
                console.error('Failed to delete round', e);
                throw e;
            }
        });
    }
};

export const clubRepository = {
    async getAllClubsSummary(): Promise<ClubSummary[]> {
        const { data, error } = await supabase
            .from('golf_clubs')
            .select(`
                id,
                name,
                golf_courses (
                    id,
                    name,
                    hole_count
                )
            `)
            .order('name', { ascending: true });

        if (error) {
            console.error('[clubRepository] getAllClubsSummary failed', error);
            return [];
        }

        return (data as unknown as DbClub[] || []).map(club => ({
            id: club.id,
            name: club.name,
            courseCount: club.golf_courses?.length ?? 0,
            courses: (club.golf_courses || []).map(c => ({
                id: c.id,
                name: c.name,
                holeCount: c.hole_count,
            })),
        }));
    },

    async getCourseWithHoles(courseId: string): Promise<ClubCourseInfo | null> {
        const { data, error } = await supabase
            .from('golf_courses')
            .select(`
                id,
                club_id,
                name,
                hole_count,
                golf_holes (
                    id,
                    course_id,
                    hole_number,
                    par,
                    handicap_idx,
                    hole_distances (
                        tee_color,
                        distance_meter
                    )
                )
            `)
            .eq('id', courseId)
            .single();

        if (error || !data) {
            console.error('[clubRepository] getCourseWithHoles failed', error);
            return null;
        }

        const holes = (data.golf_holes as unknown as DbHole[] || [])
            .sort((a, b) => a.hole_number - b.hole_number)
            .map(h => ({
                id: h.id,
                courseId: h.course_id,
                holeNumber: h.hole_number,
                par: h.par,
                handicapIdx: h.handicap_idx,
                distances: (h.hole_distances || []).map(d => ({
                    teeColor: d.tee_color,
                    distanceMeter: d.distance_meter,
                })),
            }));

        return {
            id: data.id,
            clubId: data.club_id,
            name: data.name,
            holeCount: data.hole_count,
            holes,
        };
    },

    async registerClub(payload: {
        clubName: string;
        courses: {
            courseName: string;
            holes: {
                holeNumber: number;
                par: number;
                distances?: { teeColor: string; distanceMeter: number }[];
            }[];
        }[];
    }): Promise<{ success: boolean; clubId?: string; error?: string }> {
        for (const course of payload.courses) {
            const invalidHoles = course.holes.filter(h => h.par < 3 || h.par > 7);
            if (invalidHoles.length > 0) {
                const msg = `[Par Validation Error] "${course.courseName}" course has holes with invalid Par (outside 3~7): ${invalidHoles.map(h => h.holeNumber).join(', ')}`;
                console.error(msg);
                return { success: false, error: msg };
            }
        }
        try {
            const { data: club, error: clubErr } = await supabase
                .from('golf_clubs')
                .upsert({ name: payload.clubName }, { onConflict: 'name' })
                .select('id')
                .single();

            if (clubErr || !club) throw clubErr ?? new Error('Club upsert failed');

            for (const course of payload.courses) {
                const { data: newCourse, error: courseErr } = await supabase
                    .from('golf_courses')
                    .upsert(
                        { club_id: club.id, name: course.courseName, hole_count: course.holes.length },
                        { onConflict: 'club_id,name' }
                    )
                    .select('id')
                    .single();

                if (courseErr || !newCourse) throw courseErr ?? new Error('Course upsert failed');

                const holesToInsert = course.holes.map(h => ({
                    course_id: newCourse.id,
                    hole_number: h.holeNumber,
                    par: h.par
                }));

                const { data: insertedHoles, error: holesErr } = await supabase
                    .from('golf_holes')
                    .upsert(holesToInsert, { onConflict: 'course_id,hole_number' })
                    .select('id, hole_number');

                if (holesErr || !insertedHoles) throw holesErr ?? new Error('Holes batch upsert failed');

                const distanceEntries: { hole_id: string; tee_color: string; distance_meter: number }[] = [];
                for (const hole of course.holes) {
                    if (hole.distances && hole.distances.length > 0) {
                        const holeId = insertedHoles.find(ih => ih.hole_number === hole.holeNumber)?.id;
                        if (holeId) {
                            hole.distances.forEach(d => {
                                distanceEntries.push({
                                    hole_id: holeId,
                                    tee_color: d.teeColor,
                                    distance_meter: d.distanceMeter,
                                });
                            });
                        }
                    }
                }

                if (distanceEntries.length > 0) {
                    const { error: distErr } = await supabase
                        .from('hole_distances')
                        .upsert(distanceEntries, { onConflict: 'hole_id,tee_color' });

                    if (distErr) throw distErr;
                }
            }

            console.log(`[clubRepository] "${payload.clubName}" club registered successfully (id: ${club.id})`);
            return { success: true, clubId: club.id };

            } catch (e: unknown) {
                const message = e instanceof Error ? e.message : String(e);
                console.error('[clubRepository] registerClub failed', e);
                return { success: false, error: message };
            }

    },

    async getClubFullInfo(clubId: string): Promise<ClubInfo | null> {
        const { data, error } = await supabase
            .from('golf_clubs')
            .select(`
                id,
                name,
                golf_courses (
                    id,
                    club_id,
                    name,
                    hole_count,
                    golf_holes (
                        id,
                        course_id,
                        hole_number,
                        par,
                        handicap_idx,
                        hole_distances (
                            tee_color,
                            distance_meter
                        )
                    )
                )
            `)
            .eq('id', clubId)
            .single();

        if (error || !data) {
            console.error('[clubRepository] getClubFullInfo failed', error);
            return null;
        }

        const courses = (data.golf_courses as unknown as DbCourse[] || []).map(c => ({
            id: c.id,
            clubId: c.club_id,
            name: c.name,
            holeCount: c.hole_count,
            holes: (c.golf_holes || [])
                .sort((a, b) => a.hole_number - b.hole_number)
                .map(h => ({
                    id: h.id,
                    courseId: h.course_id,
                    holeNumber: h.hole_number,
                    par: h.par,
                    handicapIdx: h.handicap_idx,
                    distances: (h.hole_distances || []).map(d => ({
                        teeColor: d.tee_color,
                        distanceMeter: d.distance_meter,
                    })),
                })),
        }));

        return {
            id: data.id,
            name: data.name,
            courses,
        };
    },
};

import { useCallback, useMemo, useState } from 'react';
import { Alert, Platform } from 'react-native';
import Toast from 'react-native-toast-message';
import * as Haptics from 'expo-haptics';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useRouter } from 'expo-router';
import { roundRepository } from '../golf.repository';
import { golfService } from '../golf.service';
import { logger } from '../../../shared/utils/logger';

export function useDashboardData(selectedRoundId?: string) {
  const queryClient = useQueryClient();
  const router = useRouter();
  const [isSyncing, setIsSyncing] = useState(false);
  const [hasPromptedSession, setHasPromptedSession] = useState(false);

  const { data: rounds, isLoading, refetch } = useQuery({
    queryKey: ['golf_rounds'],
    queryFn: () => roundRepository.getAllRounds(),
  });

  const { data: currentRoundId } = useQuery({
    queryKey: ['current_round_id'],
    queryFn: () => roundRepository.getCurrentRoundId(),
  });

  const latestRound = useMemo(() => 
    golfService.getDashboardDisplayRound(rounds || [], currentRoundId, selectedRoundId), 
  [rounds, selectedRoundId, currentRoundId]);

  const autoSync = useCallback(async () => {
    try {
      setIsSyncing(true);
      await roundRepository.pullRoundsFromSupabase();
      const { data: currentRounds } = await refetch();
      const savedId = await roundRepository.getCurrentRoundId();
      queryClient.invalidateQueries({ queryKey: ['current_round_id'] });

      // Check for incomplete session
      if (savedId && !hasPromptedSession) {
        const activeRound = currentRounds?.find(r => r.id === savedId);
        if (activeRound && activeRound.holes.length < 18) {
          setHasPromptedSession(true);

          const msg = `마지막으로 기록 중이던 라운딩(${activeRound.courseName})이 있습니다.\n이어서 기록하시겠습니까?`;
          const onContinue = () => router.push('/(tabs)/record');
          const onStartNew = async () => {
            await roundRepository.setCurrentRoundId(null);
            queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
            router.push({ pathname: '/(tabs)/record', params: { mode: 'new', t: Date.now().toString() } });
          };

          if (Platform.OS === 'web') {
            if (window.confirm(msg)) onContinue();
            else if (window.confirm("기존 기록을 종료하고 새 라운딩을 시작하시겠습니까?")) onStartNew();
          } else {
            Alert.alert("진행 중인 라운딩 감지", msg, [
              { text: "새로 시작", style: "destructive", onPress: onStartNew },
              { text: "이어서 기록", onPress: onContinue }
            ]);
          }
        }
      }
    } catch (e: unknown) {
      logger.error('[Dashboard] Auto sync failed', e);
    } finally {
      setIsSyncing(false);
    }
  }, [refetch, queryClient, hasPromptedSession, router]);

  const handleFinishRound = useCallback(async () => {
    if (!latestRound || isSyncing) return;

    const msg = "오늘의 라운딩 기록을 최종 저장하시겠습니까?\n저장 후에도 히스토리 탭에서 언제든 다시 수정할 수 있습니다.";

    const proceedSync = async () => {
      setIsSyncing(true);
      try {
        const [syncResult] = await Promise.all([
          roundRepository.syncRoundToSupabase(latestRound),
          roundRepository.setCurrentRoundId(null)
        ]);

        queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
        queryClient.invalidateQueries({ queryKey: ['golf_rounds'] });

        const successMsg = syncResult.success
          ? "라운딩이 클라우드에 성공적으로 저장되었습니다."
          : "클라우드 저장에 실패했지만, 로컬 세션은 정상 종료되었습니다.";

        Toast.show({
          type: syncResult.success ? 'success' : 'error',
          text1: syncResult.success ? '저장 완료' : '동기화 미완료',
          text2: successMsg
        });
        Haptics.notificationAsync(
          syncResult.success ? Haptics.NotificationFeedbackType.Success : Haptics.NotificationFeedbackType.Warning
        );
      } catch (e) {
        Toast.show({
          type: 'error',
          text1: '오류',
          text2: '처리 중 오류가 발생했습니다.'
        });
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
      } finally {
        setIsSyncing(false);
      }
    };

    if (Platform.OS === 'web') {
      if (window.confirm(msg)) await proceedSync();
    } else {
      Alert.alert("라운딩 종료", msg, [
        { text: "취소", style: "cancel" },
        { text: "저장 및 종료", onPress: proceedSync }
      ]);
    }
  }, [latestRound, isSyncing, queryClient]);

  const deleteRound = useCallback(async (id: string) => {
    try {
      await roundRepository.deleteRound(id);
      await queryClient.invalidateQueries({ queryKey: ['golf_rounds'] });
      await queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
      router.replace('/(tabs)/history');
      Toast.show({
        type: 'success',
        text1: '삭제 완료',
        text2: '라운딩 기록이 삭제되었습니다.'
      });
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    } catch (e) {
      logger.error('Delete flow error:', e);
      Toast.show({
        type: 'error',
        text1: '삭제 실패',
        text2: '기록을 삭제하는 중 오류가 발생했습니다.'
      });
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
    }
  }, [queryClient, router]);

  const startNewRound = useCallback(async () => {
    await roundRepository.setCurrentRoundId(null);
    queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
    router.push({ pathname: '/(tabs)/record', params: { mode: 'new', t: Date.now().toString() } });
  }, [queryClient, router]);

  const continueRound = useCallback((id?: string) => {
    if (id) {
       roundRepository.setCurrentRoundId(id);
       queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
    }
    router.push('/(tabs)/record');
  }, [queryClient, router]);

  const summaryData = useMemo(() => {
    if (!latestRound) return null;
    const s = golfService.calculateSummary(latestRound.holes);
    const score = s.totalScore - s.totalPar;
    return {
      summary: s,
      progressPercent: Math.round((latestRound.holes.length / 18) * 100),
      relativeScore: score,
      relativeScoreText: score > 0 ? `+${score}` : score < 0 ? `${score}` : 'E'
    };
  }, [latestRound]);

  const actions = useMemo(() => ({
    autoSync,
    handleFinishRound,
    deleteRound,
    startNewRound,
    continueRound,
    refetch,
  }), [autoSync, handleFinishRound, deleteRound, startNewRound, continueRound, refetch]);

  return {
    rounds,
    latestRound,
    isLoading,
    isSyncing,
    currentRoundId,
    ...summaryData,
    ...actions
  };
}

import { useCallback, useEffect, useMemo, useReducer } from 'react';
import { AppState } from 'react-native';
import Toast from 'react-native-toast-message';
import * as Haptics from 'expo-haptics';
import { useQueryClient } from '@tanstack/react-query';
import { clubRepository, roundRepository } from '../golf.repository';
import { golfService } from '../golf.service';
import { ClubSummary, GolfRound, HoleRecord, ClubCourseInfo } from '../golf.types';
import { DEFAULT_SCORES, MISS_SHOT_PATTERNS, SYNC_STATUS, TEE_COLORS } from '../golf.constants';
import { logger } from '../../../shared/utils/logger';

export interface ActiveCourseSession {
  clubId: string;
  clubName: string;
  outCourse: ClubCourseInfo;
  inCourse: ClubCourseInfo;
  combinedPars: number[];
  availableTees: string[];
}

export type SelectionStep = 'club' | 'out' | 'in' | 'tee';

interface GolfRecordState {
  currentHole: number;
  showHoleGrid: boolean;
  showScoreCard: boolean;
  selectionStep: SelectionStep;
  par: number;
  stroke: number;
  putt: number;
  ob: number;
  penalty: number;
  missShot: string;
  isParEditing: boolean;
  isFairway: boolean;
  clubs: ClubSummary[];
  activeSession: ActiveCourseSession | null;
  tempSelection: {
    club?: ClubSummary;
    outCourse?: { id: string; name: string };
    inCourse?: { id: string; name: string };
  };
  selectedTee: string;
  holeRecords: HoleRecord[];
  roundId: string;
  roundDate: string;
  isLoadingMaster: boolean;
  syncStatus: typeof SYNC_STATUS[keyof typeof SYNC_STATUS];
  pendingSyncCount: number;
}

type GolfRecordAction =
  | { type: 'SET_UI', payload: Partial<Pick<GolfRecordState, 'showHoleGrid' | 'showScoreCard' | 'selectionStep'>> }
  | { type: 'SET_CLUBS', payload: ClubSummary[] }
  | { type: 'SET_LOADING', payload: boolean }
  | { type: 'SET_SYNC_STATUS', payload: GolfRecordState['syncStatus'] }
  | { type: 'INIT_SESSION', payload: { roundId: string; roundDate: string; tee: string; records: HoleRecord[]; session: ActiveCourseSession | null } }
  | { type: 'SET_TEE_COLOR', payload: string }
  | { type: 'SET_TEMP_SELECTION', payload: Partial<GolfRecordState['tempSelection']> }
  | { type: 'SET_HOLE', payload: { holeNo: number; data: Partial<HoleRecord> } }
  | { type: 'UPDATE_SCORE_FIELD', payload: Partial<Pick<GolfRecordState, 'par' | 'stroke' | 'putt' | 'ob' | 'penalty' | 'missShot' | 'isParEditing' | 'isFairway'>> }
  | { type: 'SET_HOLE_RECORDS', payload: HoleRecord[] }
  | { type: 'SET_PENDING_SYNC_COUNT', payload: number }
  | { type: 'RESET_SESSION' };

const initialState: GolfRecordState = {
  currentHole: 1,
  showHoleGrid: false,
  showScoreCard: false,
  selectionStep: 'club',
  par: DEFAULT_SCORES.PAR,
  stroke: DEFAULT_SCORES.STROKE,
  putt: DEFAULT_SCORES.PUTT,
  ob: DEFAULT_SCORES.OB,
  penalty: DEFAULT_SCORES.PENALTY,
  missShot: MISS_SHOT_PATTERNS.NONE,
  isParEditing: false,
  isFairway: true,
  clubs: [],
  activeSession: null,
  tempSelection: {},
  selectedTee: TEE_COLORS.WHITE,
  holeRecords: [],
  roundId: "",
  roundDate: new Date().toISOString().split('T')[0],
  isLoadingMaster: true,
  syncStatus: SYNC_STATUS.IDLE,
  pendingSyncCount: 0,
};

function golfRecordReducer(state: GolfRecordState, action: GolfRecordAction): GolfRecordState {
  switch (action.type) {
    case 'SET_UI':
      return { ...state, ...action.payload };
    case 'SET_CLUBS':
      return { ...state, clubs: action.payload };
    case 'SET_LOADING':
      return { ...state, isLoadingMaster: action.payload };
    case 'SET_SYNC_STATUS':
      return { ...state, syncStatus: action.payload };
    case 'INIT_SESSION':
      return {
        ...state,
        currentHole: action.payload.records.length > 0 
          ? Math.max(...action.payload.records.map(r => r.holeNo))
          : 1,
        roundId: action.payload.roundId,
        roundDate: action.payload.roundDate,
        selectedTee: action.payload.tee,
        holeRecords: action.payload.records,
        activeSession: action.payload.session,
        selectionStep: action.payload.session ? state.selectionStep : 'club',
      };
    case 'SET_TEE_COLOR':
      return { ...state, selectedTee: action.payload };
    case 'SET_TEMP_SELECTION':
      return { ...state, tempSelection: { ...state.tempSelection, ...action.payload } };
    case 'SET_HOLE':
      return {
        ...state,
        currentHole: action.payload.holeNo,
        ...action.payload.data,
        isParEditing: false,
      };
    case 'UPDATE_SCORE_FIELD':
      return { ...state, ...action.payload };
    case 'SET_HOLE_RECORDS':
      return { ...state, holeRecords: action.payload };
    case 'SET_PENDING_SYNC_COUNT':
      return { ...state, pendingSyncCount: action.payload };
    case 'RESET_SESSION':
      return { ...initialState, clubs: state.clubs, isLoadingMaster: false };
    default:
      return state;
  }
}

export function useGolfRecord(mode?: string) {
  const queryClient = useQueryClient();
  const [state, dispatch] = useReducer(golfRecordReducer, initialState);

  // Load Initial Data
  const loadMasterAndSession = useCallback(async () => {
    try {
      dispatch({ type: 'SET_LOADING', payload: true });
      const clubList = await clubRepository.getAllClubsSummary();
      await roundRepository.retryPendingSyncs();
      const pendingCount = await roundRepository.getSyncQueueCount();
      dispatch({ type: 'SET_CLUBS', payload: clubList });
      dispatch({ type: 'SET_PENDING_SYNC_COUNT', payload: pendingCount });

      const savedId = await roundRepository.getCurrentRoundId();
      if (savedId && mode !== 'new') {
        const rounds = await roundRepository.getAllRounds();
        const currentRound = rounds.find(r => r.id === savedId);

        if (currentRound) {
          let session: ActiveCourseSession | null = null;
          if (currentRound.outCourseId && currentRound.inCourseId) {
            const [outData, inData] = await Promise.all([
              clubRepository.getCourseWithHoles(currentRound.outCourseId),
              clubRepository.getCourseWithHoles(currentRound.inCourseId)
            ]);

            if (outData && inData) {
              const outTees = outData.holes[0]?.distances.map(d => d.teeColor) || [];
              const inTees = inData.holes[0]?.distances.map(d => d.teeColor) || [];
              const commonTees = outTees.filter(t => inTees.includes(t));

              session = {
                clubId: outData.clubId,
                clubName: currentRound.courseName,
                outCourse: outData,
                inCourse: inData,
                combinedPars: golfService.calculateCombinedPars(outData.holes, inData.holes),
                availableTees: commonTees.length > 0 ? commonTees : ['White'],
              };
            }
          }
          dispatch({
            type: 'INIT_SESSION',
            payload: {
              roundId: savedId,
              roundDate: currentRound.date,
              tee: currentRound.teeColor || 'White',
              records: currentRound.holes || [],
              session
            }
          });
        } else {
          dispatch({ type: 'RESET_SESSION' });
        }
      } else {
        dispatch({ type: 'RESET_SESSION' });
      }
    } catch (e: unknown) {
      logger.error("Initialization failed", e);
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  }, [mode]);

  // Start New Round
  const startNewRound = async (tee: string) => {
    const { tempSelection, roundId, roundDate, holeRecords } = state;
    if (!tempSelection.club || !tempSelection.outCourse || !tempSelection.inCourse) return;

    dispatch({ type: 'SET_LOADING', payload: true });
    try {
      const { club, outCourse, inCourse } = tempSelection;
      const [outData, inData] = await Promise.all([
        clubRepository.getCourseWithHoles(outCourse.id),
        clubRepository.getCourseWithHoles(inCourse.id)
      ]);

      if (!outData || !inData) throw new Error("Course load failed");

      const targetId = roundId || "round_" + Date.now();
      const courseComboName = `${outData.name}-${inData.name}`;

      const session: ActiveCourseSession = {
        clubId: club.id,
        clubName: club.name,
        outCourse: outData,
        inCourse: inData,
        combinedPars: golfService.calculateCombinedPars(outData.holes, inData.holes),
        availableTees: tee ? [tee] : ['White'],
      };

      const initialRound: GolfRound = {
        id: targetId,
        date: roundId ? roundDate : new Date().toISOString().split('T')[0],
        courseName: club.name,
        courseType: courseComboName,
        outCourseId: outCourse.id,
        inCourseId: inCourse.id,
        holes: roundId ? holeRecords : [],
        updatedAt: Date.now(),
        teeColor: tee,
        memo: '',
      };

      await Promise.all([
        roundRepository.setCurrentRoundId(targetId),
        roundRepository.saveRound(initialRound)
      ]);

      dispatch({
        type: 'INIT_SESSION',
        payload: {
          roundId: targetId,
          roundDate: initialRound.date,
          tee: tee,
          records: initialRound.holes,
          session
        }
      });
      queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
      queryClient.invalidateQueries({ queryKey: ['golf_rounds'] });
      Toast.show({
        type: 'success',
        text1: '라운딩 시작',
        text2: `${club.name}에서 라운딩을 시작합니다.`
      });
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    } catch (e) {
      Toast.show({
        type: 'error',
        text1: '오류',
        text2: '라운딩 정보를 불러오지 못했습니다.'
      });
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Sync hole data when switching holes
  useEffect(() => {
    if (state.activeSession) {
      const data = golfService.getHoleData(state.currentHole, state.holeRecords, state.activeSession.combinedPars);
      dispatch({ type: 'SET_HOLE', payload: { holeNo: state.currentHole, data } });
    }
  }, [state.currentHole, state.activeSession, state.holeRecords]);

  // Auto Three-putt logic
  useEffect(() => {
    if (!state.activeSession) return;
    const nextMissShot = golfService.updateMissShotPatterns(state.missShot, state.putt);
    if (nextMissShot !== state.missShot) {
      dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { missShot: nextMissShot } });
    }
  }, [state.putt, state.activeSession, state.missShot]);


  const handleResetSession = useCallback(async () => {
    dispatch({ type: 'RESET_SESSION' });
    await roundRepository.setCurrentRoundId(null);
    queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
  }, [queryClient]);

  const handleFinishRound = useCallback(async () => {
    await roundRepository.setCurrentRoundId(null);
    queryClient.invalidateQueries({ queryKey: ['current_round_id'] });
    queryClient.invalidateQueries({ queryKey: ['golf_rounds'] });
  }, [queryClient]);

  const setPar = useCallback((v: number | ((p: number) => number)) => {
    const nextValue = typeof v === 'function' ? v(state.par) : v;
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { par: nextValue } });
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  }, [state.par]);

  const setStroke = useCallback((v: number | ((p: number) => number)) => {
    const nextValue = typeof v === 'function' ? v(state.stroke) : v;
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { stroke: nextValue } });
    Haptics.selectionAsync();
  }, [state.stroke]);

  const setPutt = useCallback((v: number | ((p: number) => number)) => {
    const nextValue = typeof v === 'function' ? v(state.putt) : v;
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { putt: nextValue } });
    Haptics.selectionAsync();
  }, [state.putt]);

  const setOb = useCallback((v: number | ((p: number) => number)) => {
    const nextValue = typeof v === 'function' ? v(state.ob) : v;
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { ob: nextValue } });
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
  }, [state.ob]);

  const setPenalty = useCallback((v: number | ((p: number) => number)) => {
    const nextValue = typeof v === 'function' ? v(state.penalty) : v;
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { penalty: nextValue } });
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
  }, [state.penalty]);

  const setMissShot = useCallback((v: string | ((p: string) => string)) => {
    const nextValue = typeof v === 'function' ? v(state.missShot) : v;
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { missShot: nextValue } });
  }, [state.missShot]);

  const setIsParEditing = useCallback((s: boolean) => 
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { isParEditing: s } }), []);

  const setIsFairway = useCallback((s: boolean) => 
    dispatch({ type: 'UPDATE_SCORE_FIELD', payload: { isFairway: s } }), []);

  const setCurrentHole = useCallback((h: number | ((prev: number) => number)) => {
    const nextHole = typeof h === 'function' ? h(state.currentHole) : h;
    dispatch({ type: 'SET_HOLE', payload: { holeNo: nextHole, data: {} } });
  }, [state.currentHole]);

  const setShowHoleGrid = useCallback((s: boolean) => dispatch({ type: 'SET_UI', payload: { showHoleGrid: s } }), []);
  const setShowScoreCard = useCallback((s: boolean) => dispatch({ type: 'SET_UI', payload: { showScoreCard: s } }), []);

  const setSelectionStep = useCallback((s: SelectionStep) => 
    dispatch({ type: 'SET_UI', payload: { selectionStep: s } }), []);

  const setTempSelection = useCallback((p: Partial<GolfRecordState['tempSelection']> | ((prev: GolfRecordState['tempSelection']) => GolfRecordState['tempSelection'])) => {
    const nextValue = typeof p === 'function' ? p(state.tempSelection) : p;
    dispatch({ type: 'SET_TEMP_SELECTION', payload: nextValue });
  }, [state.tempSelection]);

  const setSelectedTee = useCallback((t: string) => 
    dispatch({ type: 'SET_TEE_COLOR', payload: t }), []);

  const handleSaveCurrentHole = useCallback(async () => {
    if (!state.activeSession) return state.holeRecords;
    const { currentHole, par, stroke, putt, ob, penalty, missShot, isFairway, holeRecords, roundId, roundDate, selectedTee, activeSession } = state;

    const currentRecord: HoleRecord = {
      holeNo: currentHole,
      par, stroke, putt,
      isFairway,
      isGIR: golfService.isGIR(stroke, putt, par),
      ob, penalty,
      missShot: (missShot === MISS_SHOT_PATTERNS.NONE || !missShot) ? undefined : missShot
    };

    const updatedRecords = [...holeRecords.filter(r => r.holeNo !== currentHole), currentRecord].sort((a, b) => a.holeNo - b.holeNo);
    dispatch({ type: 'SET_HOLE_RECORDS', payload: updatedRecords });

    const currentRound: GolfRound = {
      id: roundId,
      date: roundDate,
      courseName: activeSession.clubName,
      courseType: `${activeSession.outCourse.name}-${activeSession.inCourse.name}`,
      outCourseId: activeSession.outCourse.id,
      inCourseId: activeSession.inCourse.id,
      holes: updatedRecords,
      updatedAt: Date.now(),
      teeColor: selectedTee,
      memo: '',
    };
    await roundRepository.saveRound(currentRound);

    dispatch({ type: 'SET_SYNC_STATUS', payload: SYNC_STATUS.SYNCING });
    roundRepository.syncRoundToSupabase(currentRound)
      .then(async (res) => {
        dispatch({ type: 'SET_SYNC_STATUS', payload: res.success ? SYNC_STATUS.SYNCED : SYNC_STATUS.FAILED });
        const pendingCount = await roundRepository.getSyncQueueCount();
        dispatch({ type: 'SET_PENDING_SYNC_COUNT', payload: pendingCount });

        if (!res.success) {
          Toast.show({
            type: 'error',
            text1: '동기화 실패',
            text2: '클라우드 저장을 실패했습니다. 나중에 자동 재시도됩니다.'
          });
          Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
        }
      })
      .catch(async () => {
        dispatch({ type: 'SET_SYNC_STATUS', payload: SYNC_STATUS.FAILED });
        const pendingCount = await roundRepository.getSyncQueueCount();
        dispatch({ type: 'SET_PENDING_SYNC_COUNT', payload: pendingCount });
      });

    queryClient.invalidateQueries({ queryKey: ['golf_rounds'] });
    return updatedRecords;
  }, [state, queryClient]);

  useEffect(() => {
    const subscription = AppState.addEventListener('change', async (nextAppState) => {
      if (nextAppState === 'active') {
        logger.info('App returned to foreground, retrying pending syncs...');
        await roundRepository.retryPendingSyncs();
        const pendingCount = await roundRepository.getSyncQueueCount();
        dispatch({ type: 'SET_PENDING_SYNC_COUNT', payload: pendingCount });
      }
    });

    return () => {
      subscription.remove();
    };
  }, []);

  const actions = useMemo(() => ({
    setCurrentHole,
    setShowHoleGrid,
    setShowScoreCard,
    setPar,
    setStroke,
    setPutt,
    setOb,
    setPenalty,
    setMissShot,
    setIsParEditing,
    setIsFairway,
    setSelectionStep,
    setTempSelection,
    setSelectedTee,
    loadMasterAndSession,
    startNewRound,
    saveCurrentHole: handleSaveCurrentHole,
    resetSession: handleResetSession,
    finishRound: handleFinishRound,
  }), [
    setCurrentHole, setShowHoleGrid, setShowScoreCard,
    setPar, setStroke, setPutt, setOb, setPenalty, setMissShot,
    setIsParEditing, setIsFairway, setSelectionStep, setTempSelection, setSelectedTee,
    loadMasterAndSession, startNewRound, handleSaveCurrentHole, handleResetSession, handleFinishRound
  ]);

  return {
    ...state,
    ...actions
  };
}

import { Link } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import React from 'react';
import { Platform } from 'react-native';

export function ExternalLink(
  props: Omit<React.ComponentProps<typeof Link>, 'href'> & { href: string }
) {
  return (
    <Link
      target="_blank"
      {...props}
      // @ts-ignore - ExternalLink은 외부 URL(string) 전용이므로 Typed Routes 타입 단언 필요
      href={props.href}
      onPress={(e) => {
        if (Platform.OS !== 'web') {
          // Prevent the default behavior of linking to the default browser on native.
          e.preventDefault();
          // Open the link in an in-app browser.
          WebBrowser.openBrowserAsync(props.href);
        }
      }}
    />
  );
}

